# =========================================================
# LOGIN PAGE
# =========================================================
if not st.session_state.logged_in:

    left_col, right_col = st.columns([1, 1], gap="small")

    with left_col:
        st.markdown(
            """
            <div class="left-panel">
                <img class="large-logo" src="data:image/jpeg;base64,">
                <h2 class="university-title">SANJAY GHODAWAT</h2>
                <div class="university-row">
                    <span class="university-word">UNIVERSITY</span>
                    <span class="kolhapur-large">KOLHAPUR</span>
                </div>
            </div>
            """.replace("data:image/jpeg;base64,", SGU_LOGO),
            unsafe_allow_html=True,
        )

    with right_col:
        st.markdown(
            """
            <div class="right-panel">
                <div class="login-heading">
                    <div class="shield">🛡️</div>
                    <h2 class="login-title">Staff Login</h2>
                    <div class="login-subtitle">Sanjay Ghodawat University ERP</div>
                </div>
            """,
            unsafe_allow_html=True,
        )

        st.markdown('<div class="field-label">User ID</div>', unsafe_allow_html=True)
        login_id = st.text_input(
            "User ID",
            key="login_id",
            placeholder="Enter your User ID",
            label_visibility="collapsed",
        )

        st.markdown('<div class="field-label">Password</div>', unsafe_allow_html=True)
        login_password = st.text_input(
            "Password",
            type="password",
            key="login_password",
            placeholder="Enter your Password",
            label_visibility="collapsed",
        )

        if st.session_state.login_error:
            st.markdown(
                f'<div class="error-box">⚠️ {st.session_state.login_error}</div>',
                unsafe_allow_html=True,
            )

        if st.button("🔒  Login to ERP   →", use_container_width=True):
            st.session_state.login_error = ""

            clean_id = login_id.strip().upper()
            clean_password = login_password.strip()

            if not clean_id or not clean_password:
                st.session_state.login_error = "Please enter User ID and Password."
                st.rerun()

            time.sleep(0.5)

            # Same Admin credentials from the supplied React file.
            if clean_id == "ADMIN123" and clean_password == "Admin@123":
                st.session_state.logged_in = True
                st.session_state.current_user = {
                    "id": "admin-001",
                    "name": "System Administrator",
                    "role": "admin",
                    "identifier": "Admin123",
                    "email": "examination@sguk.ac.in",
                    "department": "Examination Department",
                }
                st.rerun()
            else:
                # Staff-user authentication will be connected when
                # the next Admin Portal files are converted.
                st.session_state.login_error = (
                    "Invalid User ID or Password. Please contact the Administrator."
                )
                st.rerun()

        st.markdown(
            """
                <div class="security">
                    <span style="color:#34d399;">🛡</span>
                    Secure Staff Authentication
                </div>
            </div>
            """,
            unsafe_allow_html=True,
        )

    st.markdown(
        f'<div class="footer">© {datetime.now().year} Sanjay Ghodawat University, Kolhapur, Maharashtra</div>',
        unsafe_allow_html=True,
    )

else:
    # Temporary test screen. The real Admin Portal will be connected
    # after its files are converted.
    st.markdown(
        """
        <div style="
            min-height:75vh;
            display:flex;
            align-items:center;
            justify-content:center;
            color:white;
            text-align:center;
        ">
            <div>
                <h1 style="font-size:38px;">Login Successful</h1>
                <p style="color:#94a3b8;">
                    Admin Portal conversion will be connected here.
                </p>
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    if st.button("Logout"):
        st.session_state.logged_in = False
        st.session_state.current_user = None
        st.rerun()
